package com.beatoflove.standardcalculator;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.math.*;import java.util.*;
final class CurrencyPanel extends PanelUi {
 static final String[] CURRENCIES={"USD","THB","EUR","JPY","GBP","CNY","SGD","AUD","CHF","HKD","MYR","CAD","NZD","KRW","INR","IDR","PHP","VND","TWD","AED","SAR","SEK","NOK","DKK"};
 static final String[] BANKS={"Bangkok Bank","Kasikornbank","SCB","Krungthai Bank","Krungsri","ttb"};
 static final String[] BANK_URL={"https://www.bangkokbank.com/th/personal/other-services/view-rates/foreign-exchange-rates","https://www.kasikornbank.com/","https://www.scb.co.th/","https://krungthai.com/","https://www.krungsri.com/","https://www.ttbbank.com/"};
 final SharedPreferences prefs; int generation; boolean active; Runnable resumeFetch;
 CurrencyPanel(Activity a){super(a);prefs=a.getSharedPreferences("currency53",0);}
 void stop(){active=false;generation++;} void resume(){active=true;if(resumeFetch!=null)resumeFetch.run();} void attach(LinearLayout p){active=true;resumeFetch=null;LinearLayout l=screen(p,"Currency","Convert · Bank Rates · Compare");Spinner m=spin(l,"Mode",new String[]{"Convert","Bank Rates","Compare"});LinearLayout b=col();l.addView(b);selected(m,()->{generation++;resumeFetch=null;b.removeAllViews();if(m.getSelectedItemPosition()==0)convert(b);else bank(b,m.getSelectedItemPosition()==2);});}
 String s(Spinner sp){return String.valueOf(sp.getSelectedItem());}
 void convert(LinearLayout l){Spinner source=spin(l,"Rate source",new String[]{"Daily reference (Frankfurter)","Latest streamed Forex quote (cached)"});Spinner from=spin(l,"From",CURRENCIES),to=spin(l,"To",CURRENCIES);to.setSelection(1);EditText amount=input(l,"Amount","1",false);TextView out=result(l),status=text("",12,MUTE,false);l.addView(status);final BigDecimal[] rate={null};final String[] pair={""};final int[] seq={0};Runnable calc=()->{try{if(rate[0]==null||!pair[0].equals(s(from)+"/"+s(to))){out.setText("—");return;}out.setText(FinancialMath.dec(amount.getText().toString()).multiply(rate[0],FinancialMath.MC).setScale(4,RoundingMode.HALF_UP).stripTrailingZeros().toPlainString()+" "+s(to));}catch(Exception e){out.setText("—");}};Runnable fetch=()->{if(!active)return;final String src=s(from),dst=s(to),key=src+"/"+dst;final int g=generation, id=++seq[0];pair[0]=key;rate[0]=null;if(src.equals(dst)){rate[0]=BigDecimal.ONE;status.setText("Same currency");calc.run();return;}if(source.getSelectedItemPosition()==1){try{SharedPreferences quotes=a.getSharedPreferences("live_markets53",0);String raw=quotes.getString("q:"+key,"");boolean inverse=raw.isEmpty();if(inverse)raw=quotes.getString("q:"+dst+"/"+src,"");JSONObject q=new JSONObject(raw);BigDecimal r=new BigDecimal(q.getString("p"));long stamp=q.getLong("t");if(r.signum()<=0||stamp<=0)throw new Exception();rate[0]=inverse?BigDecimal.ONE.divide(r,MathContext.DECIMAL128):r;status.setText("Cached Twelve Data quote · "+new Date(stamp)+" · not live / not bank rate");}catch(Exception e){status.setText("No cached Forex quote for this pair. Open Markets → Forex first.");}calc.run();return;}String cache=prefs.getString("ref:"+key,"");try{JSONObject j=new JSONObject(cache);rate[0]=new BigDecimal(j.getString("rate"));status.setText("Cached reference · "+j.getString("date"));}catch(Exception ex){status.setText("Fetching daily reference…");}calc.run();if(src.equals(dst)){rate[0]=BigDecimal.ONE;status.setText("Same currency");calc.run();return;}PriceService.reference(src,dst,(j,err)->{if(!active||g!=generation||id!=seq[0])return;if(j==null){status.setText((rate[0]==null?"Unavailable":"Cached reference")+" · "+err);return;}try{BigDecimal r=new BigDecimal(j.getString("rate"));String date=j.getString("date");if(r.signum()<=0||!src.equals(j.getString("base"))||!dst.equals(j.getString("quote")))throw new Exception();java.time.LocalDate parsed=java.time.LocalDate.parse(date);if(parsed.isAfter(java.time.LocalDate.now().plusDays(1)))throw new Exception();if(rate[0]!=null&&!cache.isEmpty()){try{String old=new JSONObject(cache).getString("date");if(parsed.isBefore(java.time.LocalDate.parse(old))){status.setText("Cached reference · newer than provider response · "+old);return;}}catch(org.json.JSONException ignored){}}rate[0]=r;prefs.edit().putString("ref:"+key,j.toString()).apply();status.setText("Frankfurter · daily reference · "+date+"\n1 "+src+" = "+r+" "+dst);calc.run();}catch(Exception ex){status.setText("Invalid response · not updated");}});};resumeFetch=fetch;selected(source,fetch);selected(from,fetch);selected(to,fetch);watch(amount,calc);action(l,"⇅ Swap currencies",()->{int i=from.getSelectedItemPosition();from.setSelection(to.getSelectedItemPosition());to.setSelection(i);});keys(l,new String[][]{{"7","8","9"},{"4","5","6"},{"1","2","3"},{".","0","⌫"}},k->{String x=amount.getText().toString();if(k.equals("⌫"))amount.setText(x.isEmpty()?x:x.substring(0,x.length()-1));else if(!k.equals(".")||!x.contains("."))amount.setText(x+k);});action(l,"Refresh selected rate",fetch);l.addView(text("Daily institutional reference, not a live trading or bank counter rate.",12,MUTE,false));}
 void bank(LinearLayout l,boolean compare){Spinner currency=spin(l,"Foreign currency",Arrays.stream(CURRENCIES).filter(c->!c.equals("THB")).toArray(String[]::new)), direction=spin(l,"Transaction",new String[]{"Sell foreign currency → THB (bank buys)","Buy foreign currency ← THB (bank sells)"}), type=spin(l,"Rate type",new String[]{"Banknotes","Transfer"});EditText amount=input(l,"Foreign currency amount","1",false);Spinner chosen=compare?null:spin(l,"Bank",BANKS);LinearLayout rows=col();l.addView(rows);ArrayList<Runnable> updates=new ArrayList<>();Runnable build=()->{rows.removeAllViews();updates.clear();for(int i=0;i<BANKS.length;i++){if(!compare&&i!=chosen.getSelectedItemPosition())continue;final int index=i;String key="manual:"+BANKS[i]+":"+s(currency)+":"+s(direction)+":"+s(type);LinearLayout card=col();card.setBackground(bg(CARD));rows.addView(card);card.addView(text(BANKS[i],17,WHITE,true));EditText rate=input(card,"THB per 1 foreign unit · manual",prefs.getString(key,""),false);EditText fee=input(card,"Fee (THB)",prefs.getString(key+":fee","0"),false);TextView o=result(card);Runnable calc=()->{try{BigDecimal r=FinancialMath.dec(rate.getText().toString()),n=FinancialMath.dec(amount.getText().toString()),f=FinancialMath.dec(fee.getText().toString());if(r.signum()<=0||n.signum()<0||f.signum()<0)throw new Exception();boolean buy=direction.getSelectedItemPosition()==0;BigDecimal total=n.multiply(r).add(buy?f.negate():f);o.setText(FinancialMath.money(total,2,RoundingMode.HALF_UP)+" THB");}catch(Exception ex){o.setText("—");}};watch(rate,calc);watch(fee,calc);action(card,"Save manual rate",()->{prefs.edit().putString(key,rate.getText().toString()).putString(key+":fee",fee.getText().toString()).putLong(key+":time",System.currentTimeMillis()).apply();calc.run();Toast.makeText(a,"Saved manually",Toast.LENGTH_SHORT).show();});long timestamp=prefs.getLong(key+":time",0);card.addView(text(timestamp==0?"No saved rate · enter from bank website":"Manual saved: "+new java.util.Date(timestamp),12,MUTE,false));link(card,"Official bank website",BANK_URL[index]);updates.add(calc);calc.run(); } };selected(currency,build);selected(direction,build);selected(type,build);if(chosen!=null)selected(chosen,build);watch(amount,()->{for(Runnable r:updates)r.run();});link(l,"BOT daily average reference (not individual bank)","https://www.bot.or.th/th/statistics/exchange-rate.html");l.addView(text("Manual rates only. No verified bank-specific API configured. Compare same direction and transaction type; rates for JPY or other quoted lots must be normalized to one unit.",12,MUTE,false));}
}
